func TestWorkerFinishesAfterTimeout(t *testing.T) {
	synctest.Test(t, func(t *testing.T) {
		var done atomic.Bool
		var wg sync.WaitGroup
		wg.Go(func() { // sync.WaitGroup.Go: Go 1.25
			time.Sleep(time.Hour)
			done.Store(true)
		})

		synctest.Wait() // todas bloqueadas no Sleep
		if done.Load() {
			t.Fatal("terminou cedo demais")
		}
		time.Sleep(time.Hour) // relógio falso avança de imediato
		synctest.Wait()
		if !done.Load() {
			t.Fatal("deveria ter terminado")
		}
	})
}

type middleware func(http.Handler) http.Handler

func chain(h http.Handler, mws ...middleware) http.Handler {
	for _, mw := range mws {
		h = mw(h)
	}
	return h
}

func (s *server) recoverer(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if v := recover(); v != nil {
				s.log.Error("panic", "value", v)
				http.Error(w, "erro interno", 500)
			}
		}()
		next.ServeHTTP(w, r)
	})
}

