func (s *server) createItem(w http.ResponseWriter, r *http.Request) {
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // limite de 1 MiB
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields() // typos viram 400, não silêncio

	var in Item
	if err := dec.Decode(&in); err != nil {
		http.Error(w, "JSON inválido", http.StatusBadRequest)
		return
	}
	if dec.More() { // lixo depois do primeiro valor
		http.Error(w, "corpo com dados extras", http.StatusBadRequest)
		return
	}
	writeJSON(w, http.StatusCreated, in)
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(v); err != nil {
		slog.Error("encode", "err", err)
	}
}

