type Config struct {
	Addr     string
	LogLevel slog.Level
	DSN      string
}

func Load(args []string) (Config, error) {
	var c Config
	fs := flag.NewFlagSet("api", flag.ContinueOnError)
	fs.StringVar(&c.Addr, "addr", getenv("ADDR", ":8080"), "endereço HTTP")
	level := fs.String("log-level", getenv("LOG_LEVEL", "info"), "nível")
	if err := fs.Parse(args); err != nil {
		return c, err
	}
	if err := c.LogLevel.UnmarshalText([]byte(*level)); err != nil {
		return c, fmt.Errorf("LOG_LEVEL inválido: %w", err)
	}
	if c.DSN = os.Getenv("DATABASE_URL"); c.DSN == "" {
		return c, errors.New("DATABASE_URL é obrigatória")
	}
	return c, nil
}

