type WebAppReconciler struct {
	client.Client
	Scheme *runtime.Scheme
}

// +kubebuilder:rbac:groups=apps,resources=deployments,verbs=get;list;watch;create;update
// +kubebuilder:rbac:groups=web.example.com,resources=webapps,verbs=get;list;watch
// +kubebuilder:rbac:groups=web.example.com,resources=webapps/status,verbs=update;patch

func (r *WebAppReconciler) Reconcile(ctx context.Context,
	req ctrl.Request) (ctrl.Result, error) {

	var app webv1.WebApp
	if err := r.Get(ctx, req.NamespacedName, &app); err != nil {
		// apagado: os filhos caem pelo ownerReference
		return ctrl.Result{}, client.IgnoreNotFound(err)
	}

	dep := &appsv1.Deployment{ObjectMeta: metav1.ObjectMeta{
		Name: app.Name, Namespace: app.Namespace}}
	_, err := controllerutil.CreateOrUpdate(ctx, r.Client, dep, func() error {
		dep.Spec.Replicas = &app.Spec.Replicas
		dep.Spec.Template = podTemplateFor(&app) // imagem, portas...
		return controllerutil.SetControllerReference(&app, dep, r.Scheme)
	})
	if err != nil {
		return ctrl.Result{}, err // volta à fila com backoff
	}

	app.Status.ReadyReplicas = dep.Status.ReadyReplicas
	return ctrl.Result{}, r.Status().Update(ctx, &app)
}

func (r *WebAppReconciler) SetupWithManager(mgr ctrl.Manager) error {
	return ctrl.NewControllerManagedBy(mgr).
		For(&webv1.WebApp{}).
		Owns(&appsv1.Deployment{}). // eventos do filho reconciliam o pai
		Complete(r)
}
